// ucd.cpp - Unicode character properties (DESIGN 6.11): table-driven width, simple case mappings and word class
// (tables in ucdtables.cpp, generated by tools/gen_ucd.py), fixed White_Space and drawable lists.
// Bad markers (ECP_IS_BAD) have width 1, map to themselves and are neither word nor space nor drawable.
// Owner: T02.
#include "ucd.h"
#include "ucd_tables.h"

static int in_ranges(const UcRange* r, u32 n, ecp c)
{
  u32 lo = 0, hi = n;
  while (lo < hi) {
    u32 mid = (lo + hi) / 2;
    if (c < r[mid].lo) hi = mid;
    else if (c > r[mid].hi) lo = mid + 1;
    else return 1;
  }
  return 0;
}

static ecp case_map(const UcCase* t, u32 n, ecp c)
{
  u32 lo = 0, hi = n;
  const UcCase* e;
  u32 off;
  // find the last run with t.lo <= c
  while (lo < hi) {
    u32 mid = (lo + hi) / 2;
    if (t[mid].lo <= c) lo = mid + 1;
    else hi = mid;
  }
  if (lo == 0) return c;
  e = &t[lo - 1];
  off = c - e->lo;
  if (off % e->stride) return c;
  if (off / e->stride >= e->count) return c;
  return (ecp)((i32)c + e->delta);
}

int uc_width(ecp c)
{
  if (c < 0x300 || c >= 0x110000u) return 1;
  if (in_ranges(g_uc_w0, g_uc_w0_n, c)) return 0;
  if (c >= 0x1100 && in_ranges(g_uc_w2, g_uc_w2_n, c)) return 2;
  return 1;
}

ecp uc_fold(ecp c)
{
  if (c < 0x100) return g_uc_lat_fold[c];
  if (c >= 0x110000u) return c;
  return case_map(g_uc_fold, g_uc_fold_n, c);
}

ecp uc_upper(ecp c)
{
  if (c < 0x100) return g_uc_lat_upper[c];
  if (c >= 0x110000u) return c;
  return case_map(g_uc_upper, g_uc_upper_n, c);
}

ecp uc_lower(ecp c)
{
  if (c < 0x100) return g_uc_lat_lower[c];
  if (c >= 0x110000u) return c;
  return case_map(g_uc_lower, g_uc_lower_n, c);
}

int uc_is_word(ecp c)
{
  if (c < 0x100) return g_uc_lat_word[c];
  if (c >= 0x110000u) return 0;
  return in_ranges(g_uc_word, g_uc_word_n, c);
}

int uc_is_space(ecp c)                  // Unicode White_Space
{
  if (c == ' ' || (c >= 0x09 && c <= 0x0D)) return 1;
  if (c < 0x85) return 0;
  if (c == 0x85 || c == 0xA0 || c == 0x1680 || (c >= 0x2000 && c <= 0x200A) || c == 0x2028 || c == 0x2029 ||
      c == 0x202F || c == 0x205F || c == 0x3000) return 1;
  return 0;
}

int uc_is_drawable(ecp c)
{
  return (c >= 0x20 && c <= 0x52F) || (c >= 0x1E00 && c <= 0x1EFF) || (c >= 0x2000 && c <= 0x25FF) ||
         c == 0xFB01 || c == 0xFB02 || c == 0xFFFD;
}
